"""Generated by vecDSL from script productCatalog version 1.0.
Product catalogue on Pinecone: schema, writes, vector, keyword and hybrid search

Target: Pinecone (API 2026-07) through pinecone>=10.3.0,<11, Python >= 3.10.
API key: VECDSL_PINECONE_API_KEY. Other endpoints: VECDSL_PINECONE_URI (control plane),
VECDSL_PINECONE_INDEX_HOST (data plane, for example the API mock of docker-compose.yml).
"""


from __future__ import annotations

import json
import os
import sys
from typing import Any

import vecdsl_pinecone_runtime as rt


def connect(**overrides: Any) -> rt.Client:
    options: dict[str, Any] = {
        "uri": os.environ.get("VECDSL_PINECONE_URI", "https://api.pinecone.io"),
        "api_key": rt.env("VECDSL_PINECONE_API_KEY"),
        "index_host": os.environ.get("VECDSL_PINECONE_INDEX_HOST"),
    }
    options.update(overrides)
    return rt.connect(**options)


class ProductCatalog:
    def __init__(self, client: rt.Client | None = None, **overrides: Any) -> None:
        self.client = client if client is not None else connect(**overrides)

    def close(self) -> None:
        self.client.close()

    def connect_cloud(self):
        return None

    def drop_old(self):
        if rt.has_collection(self.client, name="products"):
            rt.drop_collection(self.client, name="products")

    def create_products(self):
        """Ignored on Pinecone: family on VectorIndex, maxDegree on VectorIndex, buildCandidates on VectorIndex."""
        if not rt.has_collection(self.client, name="products"):
            rt.create_collection(
                self.client,
                name="products",
                fields={
                    "embedding": {"type": "dense_vector", "dimension": 4, "metric": "cosine"},
                    "title": {"type": "string", "full_text_search": {"language": "en"}},
                },
                deployment={"cloud": "aws", "region": "us-east-1"},
            )

    def seed(self):
        return rt.insert_rows(
            self.client,
            collection={
                "name": "products",
                "namespace": "__default__",
                "key": "id",
                "key_type": "int",
                "probe": {"type": "dense_vector", "field": "embedding", "dim": 4},
                "limits": {
                    "title": {"max_length": 256},
                    "category": {"max_length": 64},
                    "tags": {"max_items": 8},
                    "embedding": {"dim": 4},
                },
            },
            rows=[
                {
                    "id": 1,
                    "title": "Milvus in action: vector database design",
                    "category": "books",
                    "price": 39.5,
                    "tags": ["vector", "database"],
                    "embedding": [0.9, 0.1, 0, 0.1],
                },
                {
                    "id": 2,
                    "title": "Approximate nearest neighbour search",
                    "category": "books",
                    "price": 52,
                    "tags": ["ann"],
                    "embedding": [0.8, 0.2, 0.1, 0],
                },
                {
                    "id": 3,
                    "title": "Espresso machine",
                    "category": "kitchen",
                    "price": 249,
                    "tags": ["coffee"],
                    "embedding": [0, 0.1, 0.9, 0.3],
                },
                {
                    "id": 4,
                    "title": "Graph databases explained",
                    "category": "books",
                    "price": 28,
                    "tags": ["graph", "database"],
                    "embedding": [0.5, 0.5, 0.2, 0.1],
                },
            ],
            wait=True,
        )

    def similar(self, query_vector, max_price):
        return rt.vector_search(
            self.client,
            collection={"name": "products", "namespace": "__default__", "key": "id", "key_type": "int"},
            field="embedding",
            vector=query_vector,
            limit=3,
            metric="cosine",
            score_min=0.2,
            filter={"$and": [{"category": {"$eq": "books"}}, {"price": {"$lte": max_price}}]},
            output=["title", "category", "price"],
        )

    def keywords(self, query_text):
        return rt.keyword_search(
            self.client,
            collection={"name": "products", "namespace": "__default__", "key": "id", "key_type": "int"},
            query=query_text,
            fields=["title"],
            limit=3,
            output=["title", "price"],
        )

    def hybrid(self, query_vector, query_text):
        return rt.hybrid_search(
            self.client,
            collection={"name": "products", "namespace": "__default__", "key": "id", "key_type": "int"},
            legs=[
                {"kind": "vector", "field": "embedding", "vector": query_vector, "metric": "cosine"},
                {"kind": "keyword", "query": query_text, "fields": ["title"]},
            ],
            limit=3,
            fusion="rrf",
            k=60,
            output=["title", "price"],
        )

    def by_id(self):
        return rt.get_rows(
            self.client,
            collection={"name": "products", "namespace": "__default__", "key": "id", "key_type": "int"},
            ids=[1, 2],
            output=["title", "price"],
        )

    def cheap_books(self):
        return rt.count(
            self.client,
            collection={"name": "products", "namespace": "__default__", "key": "id", "key_type": "int"},
            filter={"$and": [{"category": {"$eq": "books"}}, {"price": {"$lt": 40}}]},
        )

    def reprice(self):
        return rt.update_rows(
            self.client,
            collection={
                "name": "products",
                "namespace": "__default__",
                "key": "id",
                "key_type": "int",
                "probe": {"type": "dense_vector", "field": "embedding", "dim": 4},
                "limits": {
                    "title": {"max_length": 256},
                    "category": {"max_length": 64},
                    "tags": {"max_items": 8},
                    "embedding": {"dim": 4},
                },
            },
            ids=[1],
            values={"price": 35},
            wait=True,
        )

    def similar_to_first(self):
        query_vector = rt.recommend_vector(
            self.client,
            collection={"name": "products", "namespace": "__default__", "key": "id", "key_type": "int"},
            field="embedding",
            positives=[1],
            negatives=[3],
        )
        return rt.vector_search(
            self.client,
            collection={"name": "products", "namespace": "__default__", "key": "id", "key_type": "int"},
            field="embedding",
            vector=query_vector,
            limit=2,
            metric="cosine",
            output=["title"],
            filter={"id": {"$nin": [1, 3]}},
        )

    def browse(self):
        return rt.scroll(
            self.client,
            collection={"name": "products", "namespace": "__default__", "key": "id", "key_type": "int"},
            limit=10,
            filter={"tags": {"$eq": "database"}},
            output=["title", "tags"],
        )

    def remove_one(self):
        return rt.delete_rows(
            self.client,
            collection={
                "name": "products",
                "namespace": "__default__",
                "key": "id",
                "key_type": "int",
                "probe": {"type": "dense_vector", "field": "embedding", "dim": 4},
                "limits": {
                    "title": {"max_length": 256},
                    "category": {"max_length": 64},
                    "tags": {"max_items": 8},
                    "embedding": {"dim": 4},
                },
            },
            ids=[4],
            wait=True,
        )

    def remaining(self):
        return rt.count(
            self.client,
            collection={"name": "products", "namespace": "__default__", "key": "id", "key_type": "int"},
        )


def run(client: rt.Client | None = None, **parameters: Any) -> dict[str, Any]:
    names = {"queryVector": "query_vector", "maxPrice": "max_price", "queryText": "query_text"}
    unknown = sorted(set(parameters) - set(names) - set(names.values()))
    if unknown:
        raise TypeError("unknown program parameters: " + ", ".join(unknown))
    values: dict[str, Any] = {names.get(name, name): value for name, value in parameters.items()}
    values.setdefault("query_vector", [0.9, 0.1, 0, 0.1])
    values.setdefault("max_price", 60)
    values.setdefault("query_text", "vector database")
    program = ProductCatalog(client)
    try:
        return {
            "connect_cloud": program.connect_cloud(),
            "drop_old": program.drop_old(),
            "create_products": program.create_products(),
            "seed": program.seed(),
            "similar": program.similar(query_vector=values["query_vector"], max_price=values["max_price"]),
            "keywords": program.keywords(query_text=values["query_text"]),
            "hybrid": program.hybrid(query_vector=values["query_vector"], query_text=values["query_text"]),
            "by_id": program.by_id(),
            "cheap_books": program.cheap_books(),
            "reprice": program.reprice(),
            "similar_to_first": program.similar_to_first(),
            "browse": program.browse(),
            "remove_one": program.remove_one(),
            "remaining": program.remaining(),
        }
    finally:
        if client is None:
            program.close()


def _parse(arguments: list[str]) -> dict[str, Any]:
    parameters: dict[str, Any] = {}
    for argument in arguments:
        name, separator, raw = argument.partition("=")
        if not separator:
            raise SystemExit(f"expected name=value, got {argument!r}")
        try:
            parameters[name] = json.loads(raw)
        except json.JSONDecodeError:
            parameters[name] = raw
    return parameters


if __name__ == "__main__":
    print(json.dumps(run(**_parse(sys.argv[1:])), indent=2, default=str))
